		}
		if err := logs.Scan(&raw); err != nil {
			t.Fatal(err)
		}
		if err := json.Unmarshal(raw, &event); err != nil {
			t.Fatal(err)
		}
		id, _ := event.Details["outbox_id"].(string)
		if _, ok := ids[id]; ok {
			ids[id]++
		}
	}
	if err := logs.Err(); err != nil {
		t.Fatal(err)
	}
	for id, count := range ids {
