	}}, {name: "sqlite", setup: func(t *testing.T) (notifyAllChildrenStore, *sql.DB) {
		selected := storetest.StartSQLiteRuntimeStore(t)
		return selected, storetest.DatabaseForTest(selected)
	}}} {
		t.Run(tc.name, func(t *testing.T) {
			if parallelBackends {
				t.Parallel()
			}
			selected, db := tc.setup(t)
			source := notifyallchildren.LoadSource(t, notifyallchildren.Options{NumericRegistrationRows: true, NumericReporterSink: true, RegistrationUUIDField: true})
			runtime := newNotifyAllChildrenRuntime(t, selected, db, source, time.Now)
			validRunID := uuid.NewString()
			validCtx := runtimecorrelation.WithRunID(testAuthorActivityContext(context.Background()), validRunID)
			if err := runtime.manager.Run(managedConformanceExecutionContextForBundle(t, validCtx, "numeric-fan-out-reporter", runtime.sourceArtifactFact)); err != nil {
				t.Fatalf("run manager: %v", err)
			}
			publishNotifyAllChildrenRunCreatingEvent(t, validCtx, runtime, source, validRunID, "portfolio.opened", map[string]any{"portfolio_id": "portfolio-numeric-valid", "threshold": 75})
			assertNotifyAllChildrenMetadata(t, validCtx, selected, "portfolio", "portfolio_id", "portfolio-numeric-valid")
			transactions := storetest.CollectTransactions(t, selected, transactionOptions)
			t.Cleanup(func() {
				if t.Failed() {
					t.Logf("failed 500-row attempt transaction-owner snapshot (may include active work): %+v", transactions.Snapshot())
				}
			})
			issuanceStarted := time.Now()
			for batch := 0; batch < 20; batch++ {
				rows := make([]map[string]any, 0, 25)
				for row := 0; row < 25; row++ {
					ordinal := batch*25 + row
					rows = append(rows, map[string]any{"account_id": fmt.Sprintf("numeric-%03d", ordinal), "eng_roles": ordinal, "gem_score": float64(ordinal) + 0.25, "external_id": uuid.NewString()})
				}
				publishNotifyAllChildrenEventAsync(t, validCtx, runtime, source, validRunID, "portfolio.accounts.register.requested", map[string]any{"portfolio_id": "portfolio-numeric-valid", "account_ids": rows})
			}
			issuanceReached := waitNotifyAllChildrenFanOutCursor(t, runtime, validRunID, 500)
			var receipt storetest.TransactionSnapshot
			receiptDeadline := time.Now().Add(5 * time.Second)
			for {
				receipt = transactions.Snapshot()
				claims, chunks := receipt.ByOperation[storetest.TransactionFanOutClaim], receipt.ByOperation[storetest.TransactionFanOutChunk]
				if claims.WriteCommits >= 20 && chunks.WriteCommits >= 20 || time.Now().After(receiptDeadline) {
					break
				}
				time.Sleep(time.Millisecond)
			}
			t.Logf("500-row transaction-owner receipt through descendant quiescence (includes ingress, trigger, retained-session and downstream work; excludes implicit-autocommit SQL): total=%+v retained=%+v operations=%+v active=%d", receipt.Total, receipt.Retained, receipt.ByOperation, receipt.Active)
			claims, chunks := receipt.ByOperation[storetest.TransactionFanOutClaim], receipt.ByOperation[storetest.TransactionFanOutChunk]
			if claims.WriteCommits != 20 || chunks.WriteCommits != 20 || receipt.ByOperation[storetest.TransactionFanOutRelease].WriteCommits != 0 {
				t.Errorf("clean 20-chunk serving must use 20 claim + 20 atomic publication/release commits and no separate release: %+v", receipt.ByOperation)
			}
			if chunks.LastCommitAt.IsZero() || chunks.FirstCommitAt.Before(issuanceStarted) {
				t.Fatalf("500-row commit acknowledgement receipt is missing or predates submission: %+v", chunks)
			}
			issuanceElapsed := chunks.LastCommitAt.Sub(issuanceStarted)
			mergeCeiling := numericReporterIssuanceMergeCeiling(tc.name, transactionOptions.Delay, issuanceBudget)
			if tc.name == "postgres" && transactionOptions.Delay == 0 {
				t.Logf("normal PostgreSQL conformance500 provisional acceptance: original target=%s previous merge ceiling=15s provisional merge ceiling=%s", issuanceBudget, mergeCeiling)
			} else if tc.name == "sqlite" && transactionOptions.Delay == 0 {
				t.Logf("normal SQLite conformance500 lead-authorized thirty percent allowance: original target=%s previous merge ceiling=10s provisional merge ceiling=%s", issuanceBudget, mergeCeiling)
			}
			t.Logf("500-row issuance from first batch submission to final durable chunk acknowledgement: %s; cursor observed at %s; original target=%s merge ceiling=%s", issuanceElapsed, issuanceReached.Sub(issuanceStarted), issuanceBudget, mergeCeiling)
			if !fanOutRaceBuild && issuanceElapsed > mergeCeiling {
				t.Errorf("500-row issuance exceeded %s merge ceiling (original target %s): %s (transaction probe %+v)", mergeCeiling, issuanceBudget, issuanceElapsed, transactionOptions)
			}
			waitNotifyAllChildrenRuntimeWithin(t, runtime, validRunID, 5*time.Minute)
			assertNotifyAllChildrenRunEventCount(t, validCtx, db, validRunID)
			validSummary, err := selected.FanOutRunSummary(validCtx, validRunID, time.Now().UTC())
			if err != nil {
				t.Fatalf("valid FanOutRunSummary: %v", err)
			}
			if validSummary.Intents != 20 || validSummary.Cardinality != 500 || validSummary.Cursor != 500 || validSummary.Committed != 500 || validSummary.SemanticRejected != 0 || validSummary.SemanticRejectionSample != nil || validSummary.Settled != 500 || validSummary.Unsettled != 0 || validSummary.Owed != 0 {
				t.Fatalf("valid numeric reporter summary = %#v", validSummary)
			}
			assertReporterFanOutSingleChunkHistory(t, validCtx, db, validRunID)
			registrations := loadNotifyAllChildrenNumericRegistrations(t, validCtx, selected, db, validRunID)
			if len(registrations) != 500 {
				t.Fatalf("valid numeric registration events = %d, want 500", len(registrations))
			}
			first := registrations["numeric-000"]
			if first.ID == "" || first.EngRoles != 0 || first.GemScore != 0.25 {
				t.Fatalf("first numeric registration = %#v", first)
			}
			last := registrations["numeric-499"]
			if last.ID == "" || last.EngRoles != 499 || last.GemScore != 499.25 {
				t.Fatalf("last numeric registration = %#v", last)
			}
			operatorStore, ok := selected.(interface {
				LoadOperatorEvent(context.Context, string) (operatorread.OperatorEventFull, error)
			})
			if !ok {
				t.Fatalf("numeric fan-out store %T lacks operator event readback", selected)
			}
			view, err := operatorStore.LoadOperatorEvent(validCtx, last.ID)
			if err != nil {
				t.Fatalf("load numeric registration operator event: %v", err)
			}
			if view.Payload["eng_roles"] != float64(499) || view.Payload["gem_score"] != 499.25 || strings.TrimSpace(fmt.Sprint(view.Payload["external_id"])) == "" || view.Payload["eligible"] != true {
				t.Fatalf("numeric registration operator readback = payload:%#v deliveries:%#v", view.Payload, view.Deliveries)
			}
			assertNumericRegistrationDelivery(t, view)
			mixedRunID := validRunID
			mixedCtx := validCtx
			publishNotifyAllChildrenEvent(t, mixedCtx, runtime, source, mixedRunID, "portfolio.accounts.register.requested", map[string]any{"portfolio_id": "portfolio-numeric-valid", "account_ids": []map[string]any{{"account_id": "mixed-before", "eng_roles": 1, "gem_score": 1.25, "external_id": uuid.NewString()}, {"account_id": "mixed-empty-uuid", "eng_roles": 2, "gem_score": 2.25, "external_id": ""}, {"account_id": "mixed-bad-number", "eng_roles": 3, "gem_score": "not-a-number", "external_id": uuid.NewString()}, {"account_id": "mixed-after", "eng_roles": 4, "gem_score": 4.25, "external_id": uuid.NewString()}}})
			waitNotifyAllChildrenRuntimeWithin(t, runtime, mixedRunID, 5*time.Minute)
			assertNotifyAllChildrenRunEventCount(t, mixedCtx, db, mixedRunID)
			mixedSummary, err := selected.FanOutRunSummary(mixedCtx, mixedRunID, time.Now().UTC())
			if err != nil {
				t.Fatalf("mixed FanOutRunSummary: %v", err)
			}
			if mixedSummary.Intents != 21 || mixedSummary.Cardinality != 504 || mixedSummary.Cursor != 504 || mixedSummary.Committed != 502 || mixedSummary.SemanticRejected != 2 || mixedSummary.Settled != 502 || mixedSummary.Unsettled != 0 || mixedSummary.Owed != 0 {
				t.Fatalf("mixed numeric reporter summary = %#v", mixedSummary)
			}
			sample := mixedSummary.SemanticRejectionSample
			if sample == nil || sample.Ordinal != 1 || sample.Failure.Detail.Code != "emit_payload_contract_violation" {
				t.Fatalf("mixed semantic rejection sample = %#v", sample)
			}
			attrs := sample.Failure.Detail.Attributes
			actual, actualPresent := attrs["actual"].(string)
			if attrs["event"] != "portfolio/account.registered" || attrs["kind"] != "schema_mismatch" || attrs["path"] != "$.external_id" || attrs["constraint"] != "format" || attrs["expected"] != "uuid" || !actualPresent || actual != "" {
				t.Fatalf("mixed semantic rejection evidence = %#v", attrs)
			}
			rejections := loadNotifyAllChildrenSemanticRejections(t, mixedCtx, selected, db, mixedRunID)
			if len(rejections) != 2 {
				t.Fatalf("durable semantic rejections = %#v, want ordinals 1 and 2", rejections)
			}
			for ordinal, want := range map[int]map[string]string{1: {"path": "$.external_id", "constraint": "format", "expected": "uuid", "actual": ""}, 2: {"path": "$.gem_score", "constraint": "type", "expected": "number", "actual": "string"}} {
				failure, present := rejections[ordinal]
				if !present {
					t.Fatalf("durable semantic rejection ordinal %d is missing: %#v", ordinal, rejections)
				}
				for name, value := range want {
					actualValue, valuePresent := failure.Detail.Attributes[name].(string)
					if !valuePresent || actualValue != value {
						t.Fatalf("durable semantic rejection ordinal %d attribute %s = %#v, want present %q", ordinal, name, failure.Detail.Attributes[name], value)
					}
				}
			}
			mixedRegistrations := loadNotifyAllChildrenNumericRegistrations(t, mixedCtx, selected, db, mixedRunID)
			if len(mixedRegistrations) != 502 || mixedRegistrations["mixed-before"].ID == "" || mixedRegistrations["mixed-after"].ID == "" || mixedRegistrations["mixed-empty-uuid"].ID != "" || mixedRegistrations["mixed-bad-number"].ID != "" {
				t.Fatalf("mixed numeric registrations = %#v", mixedRegistrations)
			}
			for _, accountID := range []string{"mixed-before", "mixed-after"} {
				accepted, err := operatorStore.LoadOperatorEvent(mixedCtx, mixedRegistrations[accountID].ID)
				if err != nil {
					t.Fatalf("mixed accepted registration %s readback = %#v err=%v", accountID, accepted, err)
				}
				assertNumericRegistrationDelivery(t, accepted)
			}
			assertNotifyAllChildrenFanOutRunStatus(t, mixedCtx, selected, mixedRunID)
		})
	}
}

