			at    int
		}{{"rejected", 0}, {"rejected", 1}, {"load_error", 0}, {"load_error", 1}, {"compilation", 1}, {"cancelled", 0}, {"cancelled", 1}, {"prepared", 0}, {"prepared", 1}, {"panic", 0}, {"panic", 1}, {"fail_once", 0}, {"fail_once", 1}, {"workspace_first", 0}, {"workspace_first", 1}, {"retained_stop", 0}, {"retained_stop", 1}} {
