				trace.mu.Unlock()
				if second && (mode == "cancellation" || mode == "retirement") {
					close(trace.started)
					<-ctx.Done()
					close(trace.cancelled)
					<-trace.finish
					return "", ctx.Err()
				}
				if second && mode != "probe_order" {
					return "", errWorkspaceConstruction
				}
