					t.Fatalf("durable state=%q/%v status=%q/%v, want %q/%q", state, stateErr, status, statusErr, tc.state, tc.status)
				}
				if tc.discard != nil {
					if err := owner.RetireSelectedContexts(context.Background()); !errors.Is(err, tc.discard) {
